# Invoice line for a member order.
echo "member total $(( $1 * 90 / 100 ))"

lib/statement.sh.text:
#!/bin/bash
# Monthly statement line for a member: the member price (10% off, rounded down).
echo "statement member $(( $1 * 90 / 100 ))"

tests/price_test.sh.text:
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
[ "$(bash lib/statement.sh 999)" = "statement member 899" ] || { echo "statement 999"; fail=1; }
exit $fail

tests/statement_test.sh.text:
#!/bin/bash
fail=0
[ -n "$(bash lib/statement.sh 1000)" ] || { echo "statement prints nothing"; fail=1; }
exit $fail
